  let produto;
  try {
    produto = JSON.parse(texto);
  } catch {
    return { ok: false, erro: "JSON inválido" };
  }
  if (!produto || typeof produto.nome !== "string" || produto.nome === "" || typeof produto.preco !== "number" || produto.preco < 0) {
    return { ok: false, erro: "dados inválidos" };
  }
  return { ok: true, produto };
}

