const rotas = {
  "GET /ping": () => ({ status: 200, body: { ok: true } }),
  "POST /eco": (req) => ({ status: 200, body: req.body }),
};

function roteador(req) {
  const handler = rotas[req.method + " " + req.path];
  if (!handler) return { status: 404, body: { erro: "Rota não encontrada" } };
  return handler(req);
}

function roteador(req) {
  const [caminho, query = ""] = req.path.split("?");
  if (req.method !== "GET" || caminho !== "/somar") return { status: 404, body: { erro: "Rota não encontrada" } };
  const p = new URLSearchParams(query);
  const a = Number(p.get("a"));
  const b = Number(p.get("b"));
  if (p.get("a") === null || p.get("b") === null || Number.isNaN(a) || Number.isNaN(b)) {
    return { status: 400, body: { erro: "Parâmetros inválidos" } };
  }
  return { status: 200, body: { resultado: a + b } };
}

