const produtos = [{ id: 1, nome: "Mouse" }, { id: 2, nome: "Teclado" }];

function roteador(req) {
  if (req.method === "GET" && req.path.startsWith("/produtos/")) {
    const id = Number(req.path.slice("/produtos/".length));
    if (!Number.isInteger(id)) return { status: 400, body: { erro: "ID inválido" } };
    const p = produtos.find((x) => x.id === id);
    if (!p) return { status: 404, body: { erro: "Produto não encontrado" } };
    return { status: 200, body: p };
  }
  return { status: 404, body: { erro: "Rota não encontrada" } };
}

