function criarCache() {
  const dados = new Map(); // chave -> { valor, expiraEm }
  return {
    get(chave, agora) {
      const item = dados.get(chave);
      if (!item) return undefined;
      if (agora >= item.expiraEm) {
        dados.delete(chave);
        return undefined;
      }
      return item.valor;
    },
    set(chave, valor, ttlMs, agora) {
      dados.set(chave, { valor, expiraEm: agora + ttlMs });
    },
  };
}

function buscarComCache(id, cache, buscarNoBanco) {
  if (cache.has(id)) return { valor: cache.get(id), origem: "cache" };
  const valor = buscarNoBanco(id);
  cache.set(id, valor);
  return { valor, origem: "banco" };
}

