function criarLimitador(limite, janelaMs) {
  const janelas = new Map(); // ip -> { inicio, contagem }
  return function permitir(ip, agora) {
    let j = janelas.get(ip);
    if (!j || agora - j.inicio >= janelaMs) {
      j = { inicio: agora, contagem: 0 };
      janelas.set(ip, j);
    }
    j.contagem++;
    return j.contagem <= limite;
  };
}

