const ALFABETO = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

function paraBase62(n) {
  if (n === 0) return "0";
  let r = "";
  while (n > 0) {
    r = ALFABETO[n % 62] + r;
    n = Math.floor(n / 62);
  }
