}

function parenteseValido(s) {
  const pares = { ")": "(", "]": "[", "}": "{" };
  const pilha = [];
  for (const c of s) {
    if ("([{".includes(c)) pilha.push(c);
    else if (pares[c]) {
      if (pilha.pop() !== pares[c]) return false;
    }
  }
  return pilha.length === 0;
}

